import threading as _okh_threading
import time as _okh_clock


def _okh_same(ref, out, rtol=0.0):
 if out is None or len(ref) != len(out):
  return False
 for a, b in zip(ref, out):
  if a.shape != b.shape or a.dtype != b.dtype:
   return False
  if rtol == 0.0:
   if not torch.equal(a, b):
    return False
  elif not bool(((a.float() - b.float()).abs() <= rtol * a.float().abs()).all()):
   return False
 return True


def _okh_time(fns, dev, reps=25):
 flush = torch.empty(256 << 20, dtype=torch.uint8, device=dev)
 graphs = {}
 for lab, fn in fns.items():
  fn()
  torch.cuda.synchronize()
  gr = torch.cuda.CUDAGraph()
  with torch.cuda.graph(gr):
   fn()
  graphs[lab] = gr
 evs = []
 for _ in range(reps):
  for lab, gr in graphs.items():
   flush.zero_()
   a, b = torch.cuda.Event(enable_timing=True), torch.cuda.Event(enable_timing=True)
   a.record(); gr.replay(); b.record()
   evs.append((lab, a, b))
 torch.cuda.synchronize()
 ts = {lab: [] for lab in graphs}
 for lab, a, b in evs:
  ts[lab].append(a.elapsed_time(b) * 1000.0)
 del graphs
 return {lab: sorted(v)[len(v) // 2] for lab, v in ts.items()}


def _okh_pick(med, base, margin=0.97, allowed=None):
 cand = {k: v for k, v in med.items() if k != base and (allowed is None or k in allowed)}
 if not cand or base not in med:
  return base
 best = min(cand, key=cand.get)
 return best if cand[best] < margin * med[base] else base


def _okh_budget(t0, limit_s):
 return _okh_clock.perf_counter() - t0 < limit_s


def _okh_bg(fn):
 th = _okh_threading.Thread(target=fn, daemon=True)
 th.start()
 return th

_MR_VARIANT_EXTS = {}
_MR_TR_SRC = __import__("zlib").decompress(__import__("base64").b64decode('')).decode()
def _mr_variant_ext(defines=None):
    """Compile (once per define tuple) and return the extension module."""
    defines = tuple(MAIN_DEFINES if defines is None else defines)
    if DQ7 and "-DOKC_DQ7=1" not in defines:
        defines = defines + ("-DOKC_DQ7=1",)
    if defines not in _MR_VARIANT_EXTS:
        src = _MR_TR_SRC
        defs = [d for d in defines if not d.startswith("@")]
        if torch.cuda.get_device_capability()[0] < 9:
            # Small-smem dev GPUs: keep the ring at 1 slot.
            defs = [d for d in defs if not d.startswith("-DOKC_NS=") and not d.startswith("-DOKC_NSF=")]
        for d in defines:
            if d.startswith("@"):
                src = ALT_SRCS[d[1:]]
        major, minor = torch.cuda.get_device_capability()
        arch = f"{major}{minor}" + ("a" if major == 9 else "")
        tag = "_".join(d.replace("=", "").replace("-D", "").replace("@", "src").lower() for d in defines) or "main"
        _MR_VARIANT_EXTS[defines] = load_inline(
            name=f"okc_mr_tr8_observer_{tag}_sm{arch}",
            cpp_sources=CPP_SRC,
            cuda_sources=src,
            functions=["okc_run", "okc_set_pdl"],
            extra_cuda_cflags=["-O3", f"-gencode=arch=compute_{arch},code=sm_{arch}", "-lineinfo",
                               *([] if any(d.startswith("-DOKC_NS=") for d in defs) else [f"-DOKC_NS={MAIN_NS if major >= 9 else 1}"]),
                               *([] if any(d.startswith("-DOKC_NSF=") for d in defs) else [f"-DOKC_NSF={3 if major >= 9 else 1}"]), *defs],
            verbose=False,
        )
        _MR_VARIANT_EXTS[defines].okc_set_pdl(1 if PDL else 0)
    return _MR_VARIANT_EXTS[defines]
def _mr_variant_launch(data, state):
    """Run one MoE layer. Fresh output every call; no host syncs; the only
    per-call work is picking the compiled variant by token count and
    launching it in CHUNK_TOKENS-token slices."""
    cfg = data["config"]
    x = data["hidden_states"].contiguous()
    M = x.shape[0]
    assert cfg["local_start"] == state["lo"] and cfg["local_count"] == state["cnt"]
    ids = data["topk_ids"].to(torch.int32).contiguous()
    if ids.data_ptr() & 15:  # the WGS routing loads topk_ids 16 B at a time (an offset view gets an aligned copy)
        ids = ids.clone()
    tw = data["topk_weights"].to(torch.float32).contiguous()
    out = torch.empty((M, HIDDEN), dtype=torch.bfloat16, device=x.device)
    sfx = state.get("sfx", ())
    chosen = state.get('tr8', {}).get(M)
    if chosen is not None:
        ext = chosen
    elif TINY_DEFINES and M <= TINY_MAX_M:
        ext = _ext(tuple(TINY_DEFINES) + sfx)
    elif TINY2_DEFINES and M <= TINY2_MAX_M and (sfx or "-DOKC_WGS=1" not in tuple(TINY2_DEFINES)):
        ext = _ext(tuple(TINY2_DEFINES) + sfx)  # (the WGS build needs the PRMT scale decode: else MID/MAIN)
    elif MID_DEFINES and M <= MID_MAX_M:
        ext = _ext(tuple(MID_DEFINES) + sfx)
    else:
        ext = _ext(tuple(_main_defines(sfx)) + sfx)
    for m0 in range(0, M, CHUNK_TOKENS):
        m1 = min(M, m0 + CHUNK_TOKENS)
        ext.okc_run(state["w"], state["scratch"], x[m0:m1], ids[m0:m1], tw[m0:m1], out[m0:m1],
                    state["lo"], state["cnt"], state["grid"])
    return out
def _tr_probe_data(m, state, dev):
    return dict(config=dict(local_start=state['lo'], local_count=state['cnt']),
                hidden_states=torch.empty((m, HIDDEN), dtype=torch.bfloat16, device=dev),
                topk_ids=torch.empty((m, 8), dtype=torch.int32, device=dev),
                topk_weights=torch.empty((m, 8), dtype=torch.float32, device=dev))

def _tr_mutate(data, state, pattern, seed):
    # Synthetic routing is development evidence only, never inferred from a
    # timed input. Each row keeps eight distinct global expert IDs.
    import random
    rng = random.Random(20261030 + 1009 * seed + 31 * data['hidden_states'].shape[0])
    lo, cnt = state['lo'], state['cnt']
    local = list(range(lo, lo + cnt))
    remote = [e for e in range(256) if not lo <= e < lo + cnt]
    hot = rng.sample(local, 8)
    rows = []
    for t in range(data['hidden_states'].shape[0]):
        n = {'none': 0, 'one': 1, 'four': 4, 'all': 8}.get(pattern, 1 + t % 3)
        rows.append(rng.sample(hot, n) + rng.sample(remote, 8 - n))
    data['topk_ids'].copy_(torch.tensor(rows, dtype=torch.int32, device=data['topk_ids'].device))
    gen = torch.Generator(device=data['hidden_states'].device).manual_seed(151 + seed)
    data['hidden_states'].normal_(generator=gen)
    if pattern == 'none':
        data['hidden_states'].fill_(float('nan'))  # no invalid-route arithmetic
    data['topk_weights'].uniform_(.1, 1., generator=gen)
    data['topk_weights'].div_(data['topk_weights'].sum(-1, keepdim=True))
"""Prepare-only localization of TR8 byte failures; timed kernel stays parent."""

_mr_parent_prepare = prepare
_mr_parent_kernel = kernel_fn


def _mr_snapshot(state, output, n):
    # Each M<=32 call is one native launch. ctr[3] advances at its global
    # barrier, so the completed launch used (new_generation-1)&1.
    gen = int(state['scratch'][0][3].item())
    bank = (gen - 1) & 1
    ss = (state['scratch'][1][:n] if bank == 0 else
          state['scratch'][0][1032:1032+n].view(torch.float32))
    return dict(generation=gen, bank=bank, out=output.clone(), ss=ss.clone(),
        inter=state['scratch'][2][:n*HIDDEN].clone(),
        ybuf=state['scratch'][1][EMAX:EMAX+n*HIDDEN].clone())


def _mr_difference(a, b):
    report = {}
    for key in ['inter','ybuf','ss','out']:
        x, y = a[key], b[key]
        assert x.shape == y.shape and x.dtype == y.dtype
        mask = x.view(torch.uint8) != y.view(torch.uint8)
        count = int(mask.sum())
        finite = bool(torch.isfinite(x).all()) and bool(torch.isfinite(y).all())
        d = dict(byte_mismatches=count, finite=finite)
        if count:
            xf, yf = x.float().flatten(), y.float().flatten()
            changed = (x.flatten().view(torch.int16 if x.dtype == torch.bfloat16 else torch.int32)
                       != y.flatten().view(torch.int16 if y.dtype == torch.bfloat16 else torch.int32))
            idx = torch.nonzero(changed, as_tuple=False).flatten()[:6]
            xv, yv = xf[idx].cpu().tolist(), yf[idx].cpu().tolist()
            if not finite:
                xv, yv = list(map(str, xv)), list(map(str, yv))
            d.update(changed_elements=int(changed.sum()), samples=[idx.cpu().tolist(), xv, yv])
            if finite:
                delta = xf-yf
                d['max_abs'] = float(delta.abs().max())
                d['relative_L2'] = float(torch.linalg.vector_norm(delta) /
                    torch.linalg.vector_norm(xf).clamp_min(1e-30))
        report[key] = d
    return report


def _mr_case(m, state, other, variants, dev, start):
    data = _tr_probe_data(m, state, dev)
    _tr_mutate(data, state, 'one', 0)
    choices = [('A', lambda: _mr_parent_kernel(data, state), state),
               ('B', lambda: _mr_parent_kernel(data, state), state),
               ('C', lambda: _mr_parent_kernel(data, other), other)]
    if m <= 8 and ('tiny' if m <= 4 else 'tiny2') in variants:
        ext = variants['tiny' if m <= 4 else 'tiny2']
        variant_state = dict(other, tr8={m: ext})
        choices.append(('TR8', lambda: _mr_variant_launch(data, variant_state), variant_state))
    else:
        choices.append(('D', lambda: _mr_parent_kernel(data, other), other))
    last = choices[-1][0]
    graphs = {}
    for name, fn, st in choices:
        fn(); torch.cuda.synchronize(dev)
        gr = torch.cuda.CUDAGraph()
        with torch.cuda.graph(gr):
            output = fn()
        graphs[name] = gr, output, st
    for pattern in ['none','one','four','all','skew']:
        for seed in range(3):
            if not _okh_budget(start, 278.):
                print('MR_BUDGET_STOP', m, pattern, seed, flush=True)
                return
            _tr_mutate(data, state, pattern, seed)
            # Diagnostic only: count valid rows in fresh synthetic inputs.
            # This host read never enters kernel_fn or a timed graph.
            ids = data['topk_ids']
            n = int(((ids >= state['lo']) & (ids < state['lo'] + state['cnt'])).sum())
            snapshots = []
            for cycle in range(2):
                snap = {}
                for name, graph_name in [('A','A'),('A_next','A'),('B','B'),
                                          ('C','C'),('C_next','C'),(last,last)]:
                    gr, output, st = graphs[graph_name]
                    before = int(st['scratch'][0][3].item())
                    gr.replay(); torch.cuda.synchronize(dev)
                    snap[name] = _mr_snapshot(st, output, n)
                    assert snap[name]['generation'] == before + 1
                snapshots.append(snap)
            first, second = snapshots
            comparisons = {
                'A_consecutive': _mr_difference(first['A'], first['A_next']),
                'C_consecutive': _mr_difference(first['C'], first['C_next']),
                'A_repeat': _mr_difference(first['A'], second['A']),
                'same_scratch_graph': _mr_difference(first['A'], first['B']),
                'independent_scratch': _mr_difference(first['A'], first['C'])}
            if 'TR8' in first:
                comparisons['TR8_vs_same_scratch_parent'] = _mr_difference(first['C'], first['TR8'])
                comparisons['TR8_repeat'] = _mr_difference(first['TR8'], second['TR8'])
            else:
                comparisons['independent_same_scratch_graph'] = _mr_difference(first['C'], first['D'])
            if pattern == 'none':
                assert all(bool((s['out'] == 0).all()) for snap in snapshots for s in snap.values())
            payload = dict(m=m, pattern=pattern, seed=seed, local_routes=n,
                generations={k:[first[k]['generation'],second[k]['generation']] for k in first},
                banks={k:[first[k]['bank'],second[k]['bank']] for k in first},
                comparisons=comparisons)
            print('MR_CASE', __import__('json').dumps(payload, allow_nan=False), flush=True)


def prepare(weights):
    start = _okh_clock.perf_counter()
    dev = weights['w13'].device
    lo, cnt = LOCAL_START, LOCAL_EXPERTS
    sfx = ('-DOKC_PRMTSC=1',) if (PRMT_SCALES and
        _scales_prmt_exact(weights['w13_sf'][lo:lo+cnt], weights['w2_sf'][lo:lo+cnt])) else ()
    built = {}
    def build():
        try:
            with torch.cuda.device(dev):
                for key, defs in [('tiny', TINY_DEFINES), ('tiny2', TINY2_DEFINES)]:
                    if key == 'tiny2' and not sfx and '-DOKC_WGS=1' in defs:
                        continue
                    built[key] = _mr_variant_ext(tuple(defs) + sfx + ('-DOKC_ROUTE_WARP=1',))
        except Exception as e:
            print('MR_VARIANT_BUILD_ERROR', repr(e)[-1500:], flush=True)
    thread = _okh_bg(build)
    state = _mr_parent_prepare(weights)
    thread.join()
    try:
        assert tuple(state.get('sfx', ())) == sfx
        other = dict(state, scratch=_make_scratch(dev))
        print('MR_START diagnostic_only=True timed_path=33114871 variants=', sorted(built),
              'grid=', state['grid'], 'sfx=', state.get('sfx', ()), flush=True)
        for m in [1, 3, 8, 16, 32]:
            if not _okh_budget(start, 278.):
                break
            _mr_case(m, state, other, built, dev, start)
    except Exception as e:
        print('MR_ERROR', repr(e)[-1500:], flush=True)
    torch.cuda.synchronize(dev)
    print('MR_DONE', _okh_clock.perf_counter()-start, 'no_new_timed_path=True', flush=True)
    return state
